DWORD Z7ShellRestoreRecord(const WCHAR *record){WCHAR meta[Z7_PATH],data[Z7_PATH],path[Z7_PATH];HANDLE h;DWORD size,n,e=0;if(!Z7ShellJoin(record,L"PATH.DAT",meta)||!Z7ShellJoin(record,L"DATA",data))return lastError();h=CreateFileW(meta,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,0,NULL);if(h==INVALID_HANDLE_VALUE)return lastError();size=GetFileSize(h,NULL);if(size<8||size>sizeof(path)||size%2)e=ERROR_INVALID_DATA;else if(!ReadFile(h,path,size,&n,NULL)||n!=size)e=lastError();CloseHandle(h);if(e)return e;if(path[size/2-1]||path[1]!=':'||path[2]!='\\')return ERROR_INVALID_DATA;if(GetFileAttributesW(path)!=INVALID_FILE_ATTRIBUTES)return ERROR_ALREADY_EXISTS;if(!MoveFileW(data,path))return lastError();DeleteFileW(meta);RemoveDirectoryW(record);return 0;}
